import { BALANCE } from './balanceConfig';
import { cumulativeXpForLevel } from './formulas';

/**
 * Milestone-title levels: front-loaded, ever-widening, generated by
 * gap(k) = min(k, 8) starting from level 1 (level 1 itself is never a
 * milestone). Produces 2, 4, 7, 11, 16, 22, 29, 37, 45, 53, ... — matches
 * openspec/changes/virtual-dog-companion/design.md's "Milestone titles"
 * decision, validated there against the real XP curve. No fixed final
 * entry: the sequence keeps computing indefinitely (bounded only by
 * BALANCE.leveling.maxLevel), satisfying the "no final stage" guardrail in
 * proposal.md.
 */
function milestoneLevelAtIndex(index: number): number {
  let level = 1;
  for (let k = 1; k <= index; k++) {
    level += Math.min(k, 8);
  }
  return level;
}

/** 1-based index of `level` in the milestone sequence, or null if `level` isn't a milestone. Level 1 (the baseline every player starts at) is never itself a milestone. */
export function milestoneIndexForLevel(level: number): number | null {
  if (level <= 1) {
    return null;
  }
  let current = 1;
  let index = 0;
  let k = 1;
  while (current < level && current < BALANCE.leveling.maxLevel) {
    current += Math.min(k, 8);
    k++;
    index++;
  }
  return current === level ? index : null;
}

export function isMilestoneLevel(level: number): boolean {
  return milestoneIndexForLevel(level) !== null;
}

/**
 * 1-based index of the most recently reached milestone at or below `level`
 * (not necessarily an exact match) — the walk-the-sequence half of
 * `currentTitleForLevel` below, kept separate from `milestoneIndexForLevel`
 * (which only ever answers "is `level` itself exactly a milestone") since
 * the two questions are genuinely different, not a duplicate. Null below
 * the first milestone level (2).
 */
function mostRecentMilestoneIndexAtOrBelow(level: number): number | null {
  if (level <= 1) {
    return null;
  }
  let current = 1;
  let index = 0;
  let k = 1;
  let lastIndexAtOrBelow: number | null = null;
  while (current < level && current < BALANCE.leveling.maxLevel) {
    current += Math.min(k, 8);
    k++;
    index++;
    if (current <= level) {
      lastIndexAtOrBelow = index;
    }
  }
  return lastIndexAtOrBelow;
}

/**
 * Game-master-authored milestone titles, in level order (index 0 = the
 * first milestone level, level 2 — levels 2, 4, 7, 11, 16, 22, 29, 37).
 * Every title deliberately starts with a consonant sound so the hard-coded
 * "he's now a ___" / "he's a ___" render templates never break. No
 * "Master"/"Champion"/"Legend"/"Elder" — the ladder continues past 37
 * forever, so nothing here reads as an arrival.
 */
export const MILESTONE_TITLES: string[] = [
  'Doorstep Sniffer',
  'Block Wanderer',
  'Neighborhood Explorer',
  'Trail Regular',
  'Seasoned Rambler',
  'Rain-or-Shine Wayfarer',
  'Boundless Roamer',
  'Horizon Chaser',
];

/** The authored title for `level`, or null if `level` isn't a milestone or has no authored copy yet. */
export function titleForLevel(level: number): string | null {
  const index = milestoneIndexForLevel(level);
  if (index === null || index < 1 || index > MILESTONE_TITLES.length) {
    return null;
  }
  return MILESTONE_TITLES[index - 1];
}

/**
 * The Doorstep's "what title does Buddy currently hold" readout
 * (openspec/changes/home-dashboard/design.md Decision 1) — distinct from
 * `titleForLevel`, which only ever answers non-null on an exact milestone
 * level (it exists solely to drive the one-away cliffhanger). This answers
 * the persistent question for *any* level, including levels between
 * milestones. Null below the first milestone level (2) — the dog row simply
 * omits the title segment for a level-1 dog. Past the 8th authored title
 * (level 45+), returns the 8th title ("Horizon Chaser") indefinitely — the
 * same "last real thing said" behavior `titleForLevel` already has for the
 * cliffhanger, since that title remains genuinely true even though nothing
 * fresher is authored yet.
 */
export function currentTitleForLevel(level: number): string | null {
  const index = mostRecentMilestoneIndexAtOrBelow(level);
  if (index === null) {
    return null;
  }
  const clampedIndex = Math.min(index, MILESTONE_TITLES.length);
  return MILESTONE_TITLES[clampedIndex - 1];
}

/**
 * Pure trigger condition for the one-away cliffhanger (design.md: "fires at
 * walk-close when xpToNextLevel <= trailing 5-walk average XP and the next
 * level is a milestone level"). Deliberately independent of title copy —
 * callers must separately confirm titleForLevel(level + 1) is non-null
 * before actually surfacing the cliffhanger, so this function's behavior
 * (and its tests) don't depend on whether milestone copy has shipped yet.
 */
export function shouldFireCliffhanger(level: number, xp: number, trailingAverageXp: number): boolean {
  const { maxLevel } = BALANCE.leveling;
  if (level >= maxLevel) {
    return false;
  }
  const nextLevel = level + 1;
  if (!isMilestoneLevel(nextLevel)) {
    return false;
  }
  const xpToNextLevel = cumulativeXpForLevel(nextLevel) - xp;
  return xpToNextLevel <= trailingAverageXp;
}
